{
    var loaded = RoomLoader.Load(room, out var metrics);
    EngineLog.Info("Spatial", $"{metrics.FloorArea:0.0} m2, ceiling {metrics.CeilingHeight:0.00} m");
    player.position = new Vector3(0f, RoomLoader.FloorHeight(loaded), 0f);
};
scanner.StartScan();

